//go:build linux

package firewall

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
	"strconv"
	"time"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
	"github.com/cilium/ebpf/ringbuf"
	"github.com/cilium/ebpf/rlimit"

	"github.com/mohsinkhanshaik/ephemeral-sandbox-ebpf-firewall/internal/policy"
)

// The eBPF objects are generated by `make generate` (bpf2go) into
// firewall_bpfel.go / firewall_bpfel.o.

// Options configures a firewall instance bound to one cgroup.
type Options struct {
	CgroupPath    string
	Rules         []policy.Rule
	AllowICMP     bool
	AllowLoopback bool
	LogAllowed    bool
}

// Firewall is a loaded and attached set of eBPF programs for one sandbox.
type Firewall struct {
	objs  firewallObjects
	links []link.Link
	rd    *ringbuf.Reader
}

// Probe checks that the kernel accepts the programs, without attaching them.
func Probe() error {
	if err := rlimit.RemoveMemlock(); err != nil {
		return fmt.Errorf("remove memlock rlimit: %w", err)
	}
	var objs firewallObjects
	if err := loadFirewallObjects(&objs, nil); err != nil {
		return describeLoadErr(err)
	}
	return objs.Close()
}

// Load loads the programs, writes the policy and attaches to the cgroup.
func Load(opts Options) (*Firewall, error) {
	if err := rlimit.RemoveMemlock(); err != nil {
		return nil, fmt.Errorf("remove memlock rlimit: %w", err)
	}

	fw := &Firewall{}
	if err := loadFirewallObjects(&fw.objs, nil); err != nil {
		return nil, describeLoadErr(err)
	}
	ok := false
	defer func() {
		if !ok {
			fw.Close()
		}
	}()

	settings := firewallSettings{
		AllowIcmp:     b2u(opts.AllowICMP),
		LogAllowed:    b2u(opts.LogAllowed),
		AllowLoopback: b2u(opts.AllowLoopback),
	}
	if err := fw.objs.SettingsMap.Put(uint32(0), settings); err != nil {
		return nil, fmt.Errorf("write settings: %w", err)
	}

	rules := opts.Rules
	if opts.AllowLoopback {
		rules = append(append([]policy.Rule{}, rules...), policy.Loopback())
	}
	for _, r := range rules {
		k := r.Key()
		key := firewallLpmKey{Prefixlen: k.Prefixlen, Port: k.Port, Addr: k.Addr}
		if err := fw.objs.AllowV4.Put(key, uint8(1)); err != nil {
			return nil, fmt.Errorf("write rule %s: %w", r, err)
		}
	}

	attach := []struct {
		name string
		prog *ebpf.Program
		typ  ebpf.AttachType
	}{
		{"connect4", fw.objs.SbxConnect4, ebpf.AttachCGroupInet4Connect},
		{"sendmsg4", fw.objs.SbxSendmsg4, ebpf.AttachCGroupUDP4Sendmsg},
		{"connect6", fw.objs.SbxConnect6, ebpf.AttachCGroupInet6Connect},
		{"sendmsg6", fw.objs.SbxSendmsg6, ebpf.AttachCGroupUDP6Sendmsg},
		{"egress", fw.objs.SbxEgress, ebpf.AttachCGroupInetEgress},
	}
	for _, a := range attach {
		l, err := link.AttachCgroup(link.CgroupOptions{
			Path:    opts.CgroupPath,
			Attach:  a.typ,
			Program: a.prog,
		})
		if err != nil {
			return nil, fmt.Errorf("attach %s to %s: %w", a.name, opts.CgroupPath, err)
		}
		fw.links = append(fw.links, l)
	}

	rd, err := ringbuf.NewReader(fw.objs.Events)
	if err != nil {
		return nil, fmt.Errorf("open ring buffer: %w", err)
	}
	fw.rd = rd

	ok = true
	return fw, nil
}

// Run delivers events to fn until Close is called.
func (fw *Firewall) Run(fn func(Event)) error {
	var raw firewallEvent
	for {
		rec, err := fw.rd.Read()
		if errors.Is(err, ringbuf.ErrClosed) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("read ring buffer: %w", err)
		}
		if err := binary.Read(bytes.NewReader(rec.RawSample), binary.NativeEndian, &raw); err != nil {
			continue
		}
		fn(toEvent(raw))
	}
}

func toEvent(raw firewallEvent) Event {
	port := policy.Ntohs(raw.Dport)
	dst := "[::]:" + strconv.Itoa(int(port))
	if raw.Hook != 3 && raw.Hook != 4 {
		dst = netip.AddrPortFrom(policy.AddrFromKernel(raw.Daddr), port).String()
	}
	return Event{
		Time:    time.Now(),
		Hook:    hookName(raw.Hook),
		Verdict: verdictName(raw.Verdict),
		Proto:   protoName(raw.Proto),
		Dst:     dst,
	}
}

// Stats sums the per-CPU counters.
func (fw *Firewall) Stats() (Stats, error) {
	var out [3]uint64
	for i := range out {
		var perCPU []uint64
		if err := fw.objs.Stats.Lookup(uint32(i), &perCPU); err != nil {
			return Stats{}, fmt.Errorf("read stats: %w", err)
		}
		for _, v := range perCPU {
			out[i] += v
		}
	}
	return Stats{ConnDenied: out[0], ConnAllowed: out[1], PktsDropped: out[2]}, nil
}

// Close detaches programs and frees all kernel resources.
func (fw *Firewall) Close() error {
	var errs []error
	if fw.rd != nil {
		errs = append(errs, fw.rd.Close())
	}
	for _, l := range fw.links {
		errs = append(errs, l.Close())
	}
	errs = append(errs, fw.objs.Close())
	return errors.Join(errs...)
}

func describeLoadErr(err error) error {
	var ve *ebpf.VerifierError
	if errors.As(err, &ve) {
		return fmt.Errorf("kernel verifier rejected program: %+v", ve)
	}
	return fmt.Errorf("load eBPF objects: %w", err)
}

func b2u(b bool) uint32 {
	if b {
		return 1
	}
	return 0
}
